#include <bits/stdc++.h>

using namespace std;

typedef long long LL;

const int MAX_N = 10;
const int MAX_M = 25;
const int MAX_S = 1048580;
const int MOD = 1000000007;

int n, prob[MAX_N][MAX_N], match_avail[MAX_N][MAX_N], powers_of_two[MAX_M];
int row_a[MAX_N], row_b[MAX_N], dp_f[MAX_S], dp_g[MAX_S], total_states;
int state_id[70], points[MAX_M][MAX_N], state_stack[MAX_M];
bool visited[MAX_N];

int mod_pow(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (LL)result * base % MOD;
        base = (LL)base * base % MOD;
        exp >>= 1;
    }
    return result;
}

void initialize() {
    powers_of_two[0] = 1;
    for (int i = 1; i <= 20; ++i) powers_of_two[i] = powers_of_two[i-1] * 2;
    scanf("%d", &n);
    int inv_100 = mod_pow(100, MOD - 2);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            scanf("%d", &prob[i][j]);
            prob[i][j] = (LL)prob[i][j] * inv_100 % MOD;
        }
    while (n < 6) {
        ++n;
        prob[n][n] = 1;
    }
}

bool try_match(int depth) {
    if (depth > 3) return true;
    for (int candidate = 1; candidate <= 3; ++candidate) {
        if (!visited[candidate] && match_avail[row_a[depth]][row_b[candidate]]) {
            visited[candidate] = true;
            if (try_match(depth + 1)) {
                visited[candidate] = false;
                return true;
            }
            visited[candidate] = false;
        }
    }
    return false;
}

void dfs_second(int row, int col, int current_prob) {
    if (row > 3) {
        int bitmask = 0;
        for (int idx = 1; idx <= total_states; ++idx) {
            for (int k = 1; k <= 3; ++k) row_b[k] = points[idx][k];
            if (try_match(1)) bitmask |= powers_of_two[idx - 1];
        }
        dp_f[bitmask] = (dp_f[bitmask] + current_prob) % MOD;
        return;
    }
    match_avail[row_a[row]][col] = 0;
    if (col == n) dfs_second(row + 1, 1, (LL)current_prob * (1 - prob[row_a[row]][col] + MOD) % MOD);
    else dfs_second(row, col + 1, (LL)current_prob * (1 - prob[row_a[row]][col] + MOD) % MOD);
    match_avail[row_a[row]][col] = 1;
    if (col == n) dfs_second(row + 1, 1, (LL)current_prob * prob[row_a[row]][col] % MOD);
    else dfs_second(row, col + 1, (LL)current_prob * prob[row_a[row]][col] % MOD);
}

void dfs_first(int idx, int count, int mask) {
    if (count == 3) {
        state_id[mask] = ++total_states;
        state_stack[total_states] = mask;
        for (int i = 1; i <= 3; ++i) points[total_states][i] = row_a[i];
        return;
    }
    if (idx > n) return;
    dfs_first(idx + 1, count, mask);
    row_a[count + 1] = idx;
    dfs_first(idx + 1, count + 1, mask | powers_of_two[idx - 1]);
}

void precompute_g() {
    for (int i = 0; i < total_states; ++i)
        for (int j = 0; j < (1 << total_states); ++j)
            if (j & (1 << i)) dp_g[j] = (dp_g[j] + dp_g[j ^ (1 << i)]) % MOD;
}

int main() {
    initialize();
    dfs_first(1, 0, 0);
    row_a[1] = 1; row_a[2] = 2; row_a[3] = 3;
    dfs_second(1, 1, 1);
    for (int i = 0; i < (1 << total_states); ++i) {
        int transformed = 0;
        for (int j = 1; j <= total_states; ++j) {
            int complement_id = state_id[(1 << n) - 1 - state_stack[j]];
            if (i & (1 << (j - 1))) transformed |= (1 << (complement_id - 1));
        }
        dp_g[transformed] = dp_f[i];
        dp_f[i] = 0;
    }
    row_a[1] = 4; row_a[2] = 5; row_a[3] = 6;
    dfs_second(1, 1, 1);
    precompute_g();
    int answer = 0;
    for (int i = 0; i < (1 << total_states); ++i)
        answer = (answer + (LL)dp_f[i] * dp_g[(1 << total_states) - 1 - i] % MOD) % MOD;
    printf("%d\n", (1 - answer + MOD) % MOD);
    return 0;
}
